query:
SELECT r.id, r.sponsorId, s.companyName, r.submittedAt, r.status
FROM rankingsSubmissions r
LEFT JOIN sponsors s ON r.sponsorId = s.id
ORDER BY s.companyName ASC;

SELECT id, companyName FROM sponsors WHERE id NOT IN (SELECT sponsorId FROM rankingsSubmissions) ORDER BY companyName;

